# Surah Al-i-Imran (chapter 3) — part 8: ayat 72-81 (IDs 365-374)
SURAH = 3

ENTRIES = {
365: (
"اور اہلِ کتاب کا ایک گروہ کہتا ہے: ایمان لاؤ اس پر جو مسلمانوں پر نازل ہوا — دن کے آغاز میں — اور آخر میں انکار کرو — شاید کہ وہ (مسلمان) لوٹ آئیں۔",
"""۱۔ کچھ اہلِ کتاب کی شرارت — دن کے آغاز میں ایمان، شام میں انکار۔
۲۔ ’’آمِنُوا بِالَّذِي أُنزِلَ عَلَى الَّذِينَ آمَنُوا وَجْهَ النَّهَارِ وَاكْفُرُوا آخِرَهُ‘‘ — ایمان لاؤ اس پر جو مسلمانوں پر نازل ہوا — دن کے آغاز میں — اور آخر میں انکار کرو — یعنی دھوکا دینے کے لیے عارضی ایمان پھر انکار۔
۳۔ ’’لَعَلَّهُمْ يَرْجِعُونَ‘‘ — شاید کہ وہ (مسلمان) لوٹ آئیں — یعنی مسلمانوں کا اسلام سے پھرنا ان کا مقصد ہے۔
۴۔ عملی سبق: مذہب کو سیاست کا آلہ بنانے والوں سے ہوشیار رہو؛ مستقل ایمان رکھو۔"""
),
366: (
"اور (وہ کہتے ہیں): ایمان نہ لاؤ سوائے ان کے لیے جو تمہارے دین کی پیروی کریں — آپ کہیں: ہدایت اللہ کی ہدایت ہے — یہ (جھوٹ ہے) کہ کوئی ایسا شخص (ملے گا) جسے اس طرح کی دیا جائے جو تمہیں دیا گیا ہے یا وہ تمہارے رب کے پاس تم سے حجت بازی کریں — آپ کہیں: فضل اللہ کے ہاتھ میں ہے — وہ جسے چاہے عطا کرتا ہے — اور اللہ وسعت والا، جاننے والا ہے۔",
"""۱۔ اہلِ کتاب کا حسد — اللہ کے فضل پر رشک۔
۲۔ ’’قُلْ إِنَّ الْهُدَىٰ هُدَى اللّٰہِ‘‘ — آپ کہیں: ہدایت اللہ کی ہدایت ہے — یعنی ہدایت مکمل طور پر اللہ کے ہاتھ میں ہے۔
۳۔ ’’أَن يُؤْتَىٰ أَحَدٌ مِّثْلَ مَا أُوتِيتُمْ‘‘ — یہ (جھوٹ ہے) کہ کوئی ایسا شخص (ملے گا) جسے اس طرح کی دیا جائے جو تمہیں دیا گیا ہے — یعنی انہیں مسلمانوں کی یہ باتیں ناگوار ہیں کہ انہیں بھی وہی دونوں دے۔
۴۔ ’’أَوْ يُحَاجُّوكُمْ عِندَ رَبِّكُمْ‘‘ — یا وہ تمہارے رب کے پاس تم سے حجت بازی کریں — یعنی چیلنج بھی کرتے ہیں۔
۵۔ ’’قُلْ إِنَّ الْفَضْلَ بِيَدِ اللّٰہِ يُؤْتِيهِ مَن يَشَاءُ‘‘ — آپ کہیں: فضل اللہ کے ہاتھ میں ہے — وہ جسے چاہے عطا کرتا ہے — یعنی اللہ کا فضل بلا حد ہے۔
۶۔ ’’وَاللّٰہُ وَاسِعٌ عَلِيمٌ‘‘ — اور اللہ وسعت والا، جاننے والا ہے۔
۷۔ عملی سبق: اللہ کے فضل پر حسد مت کرو؛ سب کا فضل اللہ کے ہاتھ میں ہے۔"""
),
367: (
"وہ جسے چاہتا ہے اپنی رحمت کے لیے منتخب کرتا ہے — اور اللہ بہت بڑے فضل والا ہے۔",
"""۱۔ رحمت کی تقسیم — اللہ کا خاص انتخاب۔
۲۔ ’’يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ‘‘ — وہ جسے چاہتا ہے اپنی رحمت کے لیے منتخب کرتا ہے — یعنی اللہ جسے چاہے اپنی خاص رحمت سے نواز دیتا ہے۔
۳۔ ’’وَاللّٰہُ ذُو الْفَضْلِ الْعَظِيمِ‘‘ — اور اللہ بہت بڑے فضل والا ہے۔
۴۔ عملی سبق: اللہ کی رحمت مانگتے رہو؛ وہ جسے چاہے نواز دیتا ہے۔"""
),
368: (
"اور اہلِ کتاب میں سے بعض وہ ہیں کہ اگر تم ان پر بہت زیادہ (رقم) امانت رکھو تو وہ اسے تمہیں واپس لوٹا دیں — اور ان میں سے بعض وہ ہیں کہ اگر تم ان پر ایک دینار بھی امانت رکھو تو وہ اسے تمہیں واپس نہ لوٹائیں — سوائے اس کے کہ تم اس پر قائم رہو — یہ اس وجہ سے (ہے) کہ وہ کہتے ہیں: ہمارے لیے بے پڑھے (غیر اہلِ کتاب) کے بارے میں کوئی راستہ (الزام) نہیں — اور وہ اللہ پر جان بوجھ کر جھوٹ بولتے ہیں۔",
"""۱۔ تمام اہلِ کتاب یکساں نہیں — کچھ ایماندار بھی ہیں۔
۲۔ ’’مِن أَهْلِ الْكِتَابِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍ يُؤَدِّهِ إِلَيْكَ‘‘ — اہلِ کتاب میں سے بعض وہ ہیں کہ اگر تم ان پر بہت زیادہ (رقم) امانت رکھو تو وہ اسے تمہیں واپس لوٹا دیں — یعنی بہت قابلِ بھروسا لوگ بھی ہیں۔
۳۔ ’’وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍ لَّا يُؤَدِّهِ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَائِمًا‘‘ — اور ان میں سے بعض وہ ہیں کہ اگر تم ان پر ایک دینار بھی امانت رکھو تو وہ اسے تمہیں واپس نہ لوٹائیں — سوائے اس کے کہ تم اس پر قائم رہو — یعنی بغیر نگرانی کے امانت لوٹانے کو تیار نہیں۔
۴۔ ’’ذَٰلِكَ بِأَنَّهُمْ قَالُوا لَيْسَ عَلَيْنَا فِي الْأُمِّیِّينَ سَبِيلٌ‘‘ — یہ اس وجہ سے (ہے) کہ وہ کہتے ہیں: ہمارے لیے بے پڑھے (غیر اہلِ کتاب) کے بارے میں کوئی راستہ (الزام) نہیں — یعنی غیر یہودیوں کے ساتھ بدعہدی جائز سمجھتے تھے۔
۵۔ ’’وَيَقُولُونَ عَلَى اللّٰہِ الْكَذِبَ وَهُمْ يَعْلَمُونَ‘‘ — اور وہ اللہ پر جان بوجھ کر جھوٹ بولتے ہیں — یعنی بغیر ثبوت کے یہ بات گھڑتے ہیں۔
۶۔ عملی سبق: ہر انسان کو اسی کے عمل سے پرکھو؛ عمومیت نہ کرو۔"""
),
369: (
"ہاں! جو اپنا عہد پورا کرے اور (اللہ سے) ڈرے — تو بے شک اللہ پرہیزگاروں کو پسند کرتا ہے۔",
"""۱۔ عہد کی ادائیگی — تقویٰ کی اصل نشانی۔
۲۔ ’’بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِ وَاتَّقَىٰ فَإِنَّ اللّٰہَ يُحِبُّ الْمُتَّقِينَ‘‘ — ہاں! جو اپنا عہد پورا کرے اور (اللہ سے) ڈرے — تو بے شک اللہ پرہیزگاروں کو پسند کرتا ہے — یعنی عہد پورا کرنا اور تقویٰ اللہ کی محبت کی شرط ہے۔
۳۔ عملی سبق: ہر عہد پورا کرو؛ اللہ امانت داروں سے محبت کرتا ہے۔"""
),
370: (
"بے شک جو لوگ اللہ کے عہد اور اپنی قسموں کا بہت تھوڑے پر سود ادا کرتے ہیں — ان کے لیے آخرت میں کوئی حصہ نہیں — اور نہ اللہ ان سے بولے گا اور نہ انہیں قیامت کے دن دیکھے گا اور نہ انہیں پاک کرے گا — اور ان کے لیے دردناک عذاب ہے۔",
"""۱۔ عہد توڑنے اور جھوٹی قسم کھانے کی سب سے سنگین سزا۔
۲۔ ’’إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللّٰہِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا‘‘ — بے شک جو لوگ اللہ کے عہد اور اپنی قسموں کا بہت تھوڑے پر سود ادا کرتے ہیں — یعنی دین کے بدلے دنیا کی چیز لے لیتے ہیں۔
۳۔ ’’أُولَٰئِكَ لَا خَلَاقَ لَهُمْ فِي الْآخِرَۃِ‘‘ — ان کے لیے آخرت میں کوئی حصہ نہیں۔
۴۔ ’’وَلَا يُكَلِّمُهُمُ اللّٰہُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ الْقِيَامَۃِ وَلَا يُزَكِّيهِمْ‘‘ — اور نہ اللہ ان سے بولے گا اور نہ انہیں قیامت کے دن دیکھے گا اور نہ انہیں پاک کرے گا — یعنی قیامت میں اللہ کی طرف سے مکمل محرومی۔
۵۔ ’’وَلَهُمْ عَذَابٌ أَلِيمٌ‘‘ — اور ان کے لیے دردناک عذاب ہے۔
۶۔ عملی سبق: اللہ کے نام کی قسم کبھی جھوٹی مت کھاؤ؛ عہد کا احترام کرو۔"""
),
371: (
"اور بے شک ان میں سے ایک گروہ وہ ہے جو اپنی زبانوں کو کتاب کے ساتھ مروڑ تے ہیں — تاکہ تم سمجھو کہ یہ کتاب سے ہے — اور وہ کتاب سے نہیں — اور وہ کہتے ہیں کہ یہ اللہ کے پاس سے ہے — اور وہ اللہ کے پاس سے نہیں — اور وہ اللہ پر جان بوجھ کر جھوٹ بولتے ہیں۔",
"""۱۔ علماء کی تحریف — کتابِ اللہ کو اپنے فائدے کے لیے موڑنا۔
۲۔ ’’وَإِنَّ مِنْهُمْ لَفَرِيقًا يَلْوُونَ أَلْسِنَتَهُم بِالْكِتَابِ لِتَحْسَبُوهُ مِنَ الْكِتَابِ‘‘ — اور بے شک ان میں سے ایک گروہ وہ ہے جو اپنی زبانوں کو کتاب کے ساتھ مروڑ تے ہیں — تاکہ تم سمجھو کہ یہ کتاب سے ہے — یعنی الفاظ کو مروڑ کر غلط معنی گھڑتے ہیں۔
۳۔ ’’وَمَا هُوَ مِنَ الْكِتَابِ وَيَقُولُونَ هُوَ مِنْ عِندِ اللّٰہِ‘‘ — اور وہ کتاب سے نہیں — اور وہ کہتے ہیں کہ یہ اللہ کے پاس سے ہے — یعنی اپنی گھڑی بات کو اللہ کی طرف منسوب کرتے ہیں۔
۴۔ ’’وَمَا هُوَ مِنْ عِندِ اللّٰہِ وَيَقُولُونَ عَلَى اللّٰہِ الْكَذِبَ وَهُمْ يَعْلَمُونَ‘‘ — اور وہ اللہ کے پاس سے نہیں — اور وہ اللہ پر جان بوجھ کر جھوٹ بولتے ہیں۔
۵۔ عملی سبق: دین کے نام پر پیش کی گئی ہر بات کو کتابِ اللہ سے پرکھو؛ جان بوجھ کر جھوٹ بولنا بہت بڑا گناہ ہے۔"""
),
372: (
"کسی بشر کو یہ حق نہیں کہ اللہ اسے کتاب دے اور حکم اور نبوت — پھر وہ لوگوں سے کہے: تم میرے بندے بن جاؤ — اللہ کے سوا — بلکہ (وہ کہے گا): اللہ والے بن جاؤ — اس (کتاب) کی وجہ سے جو تم سکھائے گئے اور جسے تم پڑھتے رہے۔",
"""۱۔ نبی ﷺ نے کبھی نہیں کہا کہ تم میرے بندے بن جاؤ — یہ اللہ کا خود اعلان ہے۔
۲۔ ’’مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ اللّٰہُ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّةَ‘‘ — کسی بشر کو یہ حق نہیں کہ اللہ اسے کتاب دے اور حکم اور نبوت — یعنی نبوت کی بڑی ذمہ داری کے بعد کسی کو رب بنا لینا غلط ہے۔
۳۔ ’’ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا عِبَادًا لِّي مِن دُونِ اللّٰہِ‘‘ — پھر وہ لوگوں سے کہے: تم میرے بندے بن جاؤ — اللہ کے سوا — یعنی کوئی نبی یہ نہیں کہہ سکتا۔
۴۔ ’’وَلَٰكِن كُونُوا رَبَّانِيِّينَ بِمَا كُنتُمْ تُعَلِّمُونَ الْكِتَابَ وَبِمَا كُنتُمْ تَدْرُسُونَ‘‘ — بلکہ (وہ کہے گا): اللہ والے بن جاؤ — اس (کتاب) کی وجہ سے جو تم سکھائے گئے اور جسے تم پڑھتے رہے — یعنی تعلیم و تدریس کا أصل مقصد اللہ والا بننا ہے۔
۵۔ عملی سبق: کسی انسان کو خدا نہ بنائیں؛ نبیوں کی اتباع اللہ کی اطاعت تک محدود ہے۔"""
),
373: (
"اور نہ (وہ) یہ حکم دے کہ فرشتوں اور نبیوں کو رب بناؤ — کیا وہ تمہیں کفر کا حکم دے گا بعد اس کے کہ تم مسلمان ہو چکے ہو۔",
"""۱۔ فرشتوں اور نبیوں کی عبادت بھی شرک ہے۔
۲۔ ’’وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا الْمَلَائِكَۃَ وَالنَّبِيِّينَ أَرْبَابًا‘‘ — اور نہ (وہ) یہ حکم دے کہ فرشتوں اور نبیوں کو رب بناؤ — یعنی کسی کو اللہ کا مقام دینا کفر ہے۔
۳۔ ’’أَيَأْمُرُكُم بِالْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ‘‘ — کیا وہ تمہیں کفر کا حکم دے گا بعد اس کے کہ تم مسلمان ہو چکے ہو — یعنی مسلمان ہونے کے بعد ایسا حکم ناممکن ہے۔
۴۔ عملی سبق: نبیوں اور فرشتوں کا احترام کرو مگر ان کی عبادت نہ کرو؛ صرف اللہ کی عبادت کرو۔"""
),
374: (
"اور جب اللہ نے انبیاء سے عہد لیا — جو میں تمہیں کتاب اور حکمت میں سے دیتا ہوں — پھر تمہارے پاس ایسا رسول آئے جو تصدیق کرنے والا ہو اس کی جو تمہارے پاس ہے — ضرور تم اس پر ایمان لاؤ گے اور ضرور اس کی مدد کرو گے — کہا: کیا تم نے اقرار کیا اور اس پر میرا بھاری ذمہ لیا؟ — انہوں نے کہا: ہم نے اقرار کیا — کہا: پس تم گواہ رہؤ اور میں بھی تمہارے ساتھ گواہوں میں سے ہوں۔",
"""۱۔ تمام انبیاء سے لے کر نبی ﷺ کی تصدیق کا عہد — نبوت کا واحد سلسلہ۔
۲۔ ’’وَإِذْ أَخَذَ اللّٰہُ مِيثَاقَ النَّبِيِّينَ لَمَا آتَيْتُكُم مِّن كِتَابٍ وَحِكْمَۃٍ‘‘ — اور جب اللہ نے انبیاء سے عہد لیا — جو میں تمہیں کتاب اور حکمت میں سے دیتا ہوں — یعنی اللہ نے ہر نبی سے عہد لیا۔
۳۔ ’’ثُمَّ جَاءَكُمْ رَسُولٌ مُّصَدِّقٌ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِ وَلَتَنصُرُنَّهُ‘‘ — پھر تمہارے پاس ایسا رسول آئے جو تصدیق کرنے والا ہو اس کی جو تمہارے پاس ہے — ضرور تم اس پر ایمان لاؤ گے اور ضرور اس کی مدد کرو گے — یعنی نبی ﷺ کے آنے پر ہر نبی اور ان کی امت پر ایمان و نصرت واجب ہوگی۔
۴۔ ’’قَالَ أَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِي‘‘ — کہا: کیا تم نے اقرار کیا اور اس پر میرا بھاری ذمہ لیا؟ — یعنی اللہ نے پوچھا اور نبیوں نے اقرار کیا۔
۵۔ ’’قَالُوا أَقْرَرْنَا قَالَ فَاشْهَدُوا وَأَنَا مَعَكُم مِّنَ الشَّاهِدِينَ‘‘ — انہوں نے کہا: ہم نے اقرار کیا — کہا: پس تم گواہ رہؤ اور میں بھی تمہارے ساتھ گواہوں میں سے ہوں — یعنی اللہ خود بھی گواہ ہے۔
۶۔ عملی سبق: نبی ﷺ پر ایمان ہر پچھلے نبی کا عہد ہے؛ یہ عہد پورا کرنا ہم سب کی ذمہ داری ہے۔"""
),
}
